bool Read_GfxEngineTextureNamesResult(const WasmValue& input, GfxEngineTextureNamesResult& output, NativeCallStorage& storage, std::string& error)
{
	const auto* record = std::get_if<WasmValueRecord>(&input.storage);
	if (record == nullptr) { error = "Wasm argument is not a record"; return false; }
	const auto* value_names = FindRecordField(*record, "names", error);
	if (value_names == nullptr) return false;
	const auto* list_names = std::get_if<WasmValueList>(&(*value_names).storage);
	if (list_names == nullptr) { error = "Wasm argument is not a list"; return false; }
	auto& native_names = storage.Make<std::vector<std::string>>();
	native_names.reserve(list_names->size());
	for (const auto& item : *list_names) {
		std::string item_value{};
		auto& stored_string_item_value = storage.Make<std::string>();
		if (!ReadString(item, stored_string_item_value, error)) { return false; }
		item_value = stored_string_item_value.c_str();
		native_names.push_back(std::move(item_value));
	}
	auto& pointers_names = storage.Make<std::vector<const char*>>();
	pointers_names.reserve(native_names.size());
	for (const auto& item : native_names) pointers_names.push_back(item.c_str());
	output.names = pointers_names.data();
	if (!AssignCount(list_names->size(), output.count, error)) { return false; }
	return true;
}

WasmValue Write_GfxEngineTextureNamesResult(const GfxEngineTextureNamesResult& value)
{
	WasmValueRecord fields;
	fields.emplace("names", WriteNativeList(value.names, value.count, [](const auto& value) { return WasmValue::String(value == nullptr ? std::string{} : std::string(value)); }));
	return WasmValue::Record(std::move(fields));
}

