bool Read_GfxObjectBufferUniformsQuery(const WasmValue& input, GfxObjectBufferUniformsQuery& output, NativeCallStorage& storage, std::string& error)
{
	const auto* record = std::get_if<WasmValueRecord>(&input.storage);
	if (record == nullptr) { error = "Wasm argument is not a record"; return false; }
	const auto* value_objectID = FindRecordField(*record, "objectID", error);
	if (value_objectID == nullptr) return false;
	if (!ReadScalar(*value_objectID, output.objectID, error)) { return false; }
	const auto* value_values = FindRecordField(*record, "values", error);
	if (value_values == nullptr) return false;
	const auto* list_values = std::get_if<WasmValueList>(&(*value_values).storage);
	if (list_values == nullptr) { error = "Wasm argument is not a list"; return false; }
	auto& native_values = storage.Make<std::vector<float>>();
	native_values.reserve(list_values->size());
	for (const auto& item : *list_values) {
		float item_value{};
		if (!ReadScalar(item, item_value, error)) { return false; }
		native_values.push_back(std::move(item_value));
	}
	output.values = native_values.data();
	if (!AssignCount(list_values->size(), output.count, error)) { return false; }
	const auto* value_offset = FindRecordField(*record, "offset", error);
	if (value_offset == nullptr) return false;
	if (!ReadScalar(*value_offset, output.offset, error)) { return false; }
	return true;
}

