	if (value_values == nullptr) return false;
	const auto* array_values_values = std::get_if<WasmValueList>(&(*value_values).storage);
	if (array_values_values == nullptr || array_values_values->size() != 4u) { error = "Wasm fixed array has the wrong length"; return false; }
